#!/usr/bin/env bash
# Regenerates every result file in this folder: re-scores the 31 checkpoints under the legacy and the apodized
# metric mask, then writes the markdown table. The script skips a run whose JSON already exists, so delete
# reports/metric_mask_reeval_r8/*.json first to recompute. Needs the checkpoints (untracked, see manifest.json) and one GPU.
set -euo pipefail
cd "$(dirname "$0")/../.."
python scripts/eval/reeval_metric_mask_r8.py --runs conv2d_varnet_r8_brain_knee_floor0.05 conv2d_varnet_r8_brain_knee_floor0.05_ahain conv2d_varnet_r8_brain_knee_floor0.05_clamp10_leak0.05 conv2d_varnet_r8_brain_knee_floor0.05_draws2 conv2d_varnet_r8_brain_knee_floor0.05_imginput conv2d_varnet_r8_brain_knee_floor0.05_imginput_headbias conv2d_varnet_r8_brain_knee_floor0.05_imginput_headmlp_ln_clipsplit loupe2d_cgsense_r4_brain_knee_anatcond loupe2d_cgsense_r4_brain_knee_shared loupe2d_cgsense_r8_brain_knee_anatcond loupe2d_cgsense_r8_brain_knee_anatcond_bilinear_const_100ep loupe2d_cgsense_r8_brain_knee_anatcond_sharedinit loupe2d_cgsense_r8_brain_knee_dcm_anatcond loupe2d_cgsense_r8_brain_knee_dcm_prototable loupe2d_cgsense_r8_brain_knee_dcm_shared loupe2d_cgsense_r8_brain_knee_ecalib_c10 loupe2d_cgsense_r8_brain_knee_ecalib_c24 loupe2d_cgsense_r8_brain_knee_prototable loupe2d_cgsense_r8_brain_knee_prototable_bilinear_const_100ep loupe2d_cgsense_r8_brain_knee_shared loupe2d_cgsense_r8_brain_knee_shared_bilinear_50ep loupe2d_cgsense_r8_brain_knee_shared_bilinear_50ep_seed43 loupe2d_cgsense_r8_brain_knee_shared_bilinear_const_100ep loupe2d_cgsense_r8_brain_knee_shared_bilinear_nomask_50ep loupe2d_cgsense_r8_brain_knee_shared_cont loupe2d_cgsense_r8_brain_knee_shared_seed43 loupe2d_varnet_r8_brain_knee_anatcond_100ep random_mask_varnet_r8_brain_knee varnet_caipi2d_r4_promptmr_blind_seed42 varnet_caipi2d_r4_promptmr_cond_seed42 varnet_caipi2d_r4_promptmr_cond_seed43 --device cuda:0 --out reports/metric_mask_reeval_r8
python scripts/eval/reeval_metric_mask_r8.py --table --out reports/metric_mask_reeval_r8 > reports/metric_mask_reeval_r8/table.md
